import os
from mcp.server.fastmcp import FastMCP
from mcp.server.transport_security import TransportSecuritySettings
from mcp.types import ToolAnnotations
from starlette.responses import PlainTextResponse, HTMLResponse
from checker import check_site, summarize, CheckError

mcp = FastMCP(
    "Pillar AI Visibility Checker",
    instructions="Checks whether a public website is technically ready to be found and cited by AI search tools. It inspects one page, robots.txt and llms.txt. It does not measure rankings or AI mentions.",
    host="0.0.0.0", port=int(os.environ.get("PORT", "8000")),
    stateless_http=True, json_response=True,
    transport_security=TransportSecuritySettings(enable_dns_rebinding_protection=False),
)

RO = ToolAnnotations(readOnlyHint=True, destructiveHint=False, idempotentHint=True, openWorldHint=False)

@mcp.tool(title="Check AI visibility readiness", annotations=RO,
          description="Use when the user wants to know whether a public website is set up to be found by AI search and answer engines (ChatGPT search, Perplexity, Google AI features). Fetches one public page plus robots.txt and llms.txt and returns a pass/fix checklist: title, meta description, H1, canonical, noindex, Open Graph, JSON-LD, text in initial HTML, and which AI crawlers robots.txt allows or blocks. Do not use it to predict rankings or measure whether AI tools mention a brand.")
def check_ai_visibility_readiness(url: str) -> dict:
    """url: public website address, for example example.com or https://example.com/pricing"""
    try:
        r = check_site(url)
    except CheckError as e:
        return {"error": str(e)}
    r["summary"] = summarize(r)
    return r

@mcp.tool(title="List AI crawler names", annotations=RO,
          description="Use when the user asks which AI crawlers and user agents exist and what each is for (GPTBot, OAI-SearchBot, ChatGPT-User, PerplexityBot, ClaudeBot, Google-Extended, CCBot). Static reference, no network access.")
def list_ai_crawlers() -> dict:
    from checker import AI_BOTS
    return {"crawlers": [{"user_agent": k, "purpose": v} for k, v in AI_BOTS.items()],
            "note": "Blocking a training crawler does not necessarily block the search crawler of the same company. Check each user agent separately."}

@mcp.custom_route("/", methods=["GET"])
async def home(request):
    return HTMLResponse('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pillar AI Visibility Checker</title><meta name="description" content="Read-only AI visibility technical checks through the Pillar MCP endpoint."><style>body{background:#f6f2ea;color:#263a31;font:18px/1.6 system-ui;max-width:660px;margin:40px auto;padding:24px}a{color:#2f5d50}</style></head><body><h1>Pillar AI Visibility Checker</h1><p>A read-only MCP service that checks one public page, robots.txt and llms.txt. It does not measure rankings or AI mentions.</p><p>MCP endpoint: <code>/mcp</code></p><p><a href="https://pillar-agent-fabric.onrender.com/ai-visibility">AI Visibility Audit</a> or <a href="https://pillar-fabric.onrender.com/contact?product=AI%20Checker">contact Pillar Fabric</a>.</p></body></html>')

@mcp.custom_route("/healthz", methods=["GET"])
async def health(request):
    return PlainTextResponse("ok")

from launch_mcp import build
app = build(mcp)
_launch_ns={}
exec('"""Shared SEO slots for Pillar Fabric hosts (pure ASGI, no deps).\n\n- Serves the IndexNow key file at /<key>.txt (the key is public by design).\n- Serves Open Graph images at /og/<name>.png when og_assets.py is present (hub host).\n- Injects, into HTML pages only, before </head>:\n    * search-engine verification meta tags from env SEO_VERIFY_TAGS\n      (only <meta name="..." content="..."> tags are accepted)\n    * Organization JSON-LD with sameAs from env SEO_SAMEAS (comma list)\n      unless the page already declares an Organization.\n    * og:image and Twitter card tags when the page does not declare them\n      (title and description are read from the page itself).\n"""\nimport base64\nimport html as _html\nimport json\nimport os\nimport re\n\ntry:\n    from .og_assets import IMAGES as _OG_IMAGES\nexcept Exception:\n    try:\n        from og_assets import IMAGES as _OG_IMAGES\n    except Exception:\n        _OG_IMAGES = {}\n\nINDEXNOW_KEY = os.environ.get("INDEXNOW_KEY", "").strip() or "24425da165ffef02a27ca60109d79736"\nORG_NAME = "Pillar Fabric"\nORG_URL = "https://pillar-fabric.onrender.com/"\nOG_BASE = os.environ.get("OG_BASE", "https://pillar-fabric.onrender.com").rstrip("/")\nDEFAULT_SAMEAS = ["https://x.com/usepillar_ai", "https://github.com/fizzle89"]\nMETA_RE = re.compile(r\'<meta\\s+name="[a-zA-Z0-9_.:-]{3,60}"\\s+content="[^"<>]{1,200}"\\s*/?>\')\nOG_PATH_RE = re.compile(r"^/og/([a-z]+)\\.png$")\n\n\ndef _org_block() -> bytes:\n    same = [s.strip() for s in os.environ.get("SEO_SAMEAS", "").split(",") if s.strip().startswith("https://")] or DEFAULT_SAMEAS\n    org = {"@context": "https://schema.org", "@type": "Organization", "name": ORG_NAME, "url": ORG_URL, "sameAs": same}\n    return (\'<script type="application/ld+json">\' + json.dumps(org, separators=(",", ":")) + "</script>").encode()\n\n\ndef _verify_block() -> bytes:\n    raw = os.environ.get("SEO_VERIFY_TAGS", "")\n    return "".join(META_RE.findall(raw)).encode()\n\n\ndef _image_key(host: str, path: str) -> str:\n    host = (host or "").lower()\n    if "tenda" in host:\n        return "tenda"\n    if "monitoring" in host:\n        return "monitoring"\n    if "clips" in host:\n        return "clips"\n    if "agent-fabric" in host:\n        return "visibility" if path.startswith("/ai-visibility") else "security"\n    return "pillar"\n\n\ndef _attr(text: str, pattern: str) -> str:\n    m = re.search(pattern, text, re.I | re.S)\n    return _html.unescape(m.group(1)).strip() if m else ""\n\n\ndef _social_block(body: bytes, host: str, path: str) -> tuple:\n    """Return (tags_to_add, body) with a summary twitter:card upgraded to large."""\n    text = body.decode("utf-8", "ignore")\n    key = _image_key(host, path)\n    image = f"{OG_BASE}/og/{key}.png"\n    title = _attr(text, r\'<meta[^>]+property="og:title"[^>]+content="([^"]*)"\') or _attr(text, r"<title[^>]*>(.*?)</title>")\n    desc = _attr(text, r\'<meta[^>]+property="og:description"[^>]+content="([^"]*)"\') or _attr(text, r\'<meta[^>]+name="description"[^>]+content="([^"]*)"\')\n    esc = lambda s: _html.escape(s, quote=True)\n    add = ""\n    if \'property="og:image"\' not in text:\n        add += (f\'<meta property="og:image" content="{image}">\'\n                \'<meta property="og:image:type" content="image/png">\'\n                \'<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">\'\n                f\'<meta property="og:image:alt" content="{esc(title or ORG_NAME)}">\')\n    if \'name="twitter:card"\' in text:\n        body = re.sub(rb\'(<meta\\s+name="twitter:card"\\s+content=")summary(")\', rb"\\1summary_large_image\\2", body)\n    else:\n        add += \'<meta name="twitter:card" content="summary_large_image">\'\n    if \'name="twitter:title"\' not in text and title:\n        add += f\'<meta name="twitter:title" content="{esc(title)}">\'\n    if \'name="twitter:description"\' not in text and desc:\n        add += f\'<meta name="twitter:description" content="{esc(desc)}">\'\n    if \'name="twitter:image"\' not in text:\n        add += f\'<meta name="twitter:image" content="{image}">\'\n    return add.encode(), body\n\n\n\n# Launch hygiene: metadata, a real central inquiry page and a readable not-found page.\nFAVICON=\'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32"><rect width="32" height="32" rx="7" fill="#183d35"/><path d="M9 25V7h7a6 6 0 010 12h-3v6zm4-10h3a2 2 0 000-4h-3z" fill="#eee9db"/></svg>\'\ndef _page(title,content):\n    return (\'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>\'+_html.escape(title)+\' | Pillar Fabric</title><meta name="description" content="\'+_html.escape(title,quote=True)+\' for Pillar Fabric products."><link rel="icon" href="/launch-favicon.svg"><style>body{margin:0;background:#f6f2ea;color:#1e2420;font:17px/1.6 system-ui}main{max-width:620px;margin:48px auto;padding:24px}h1{font:40px Georgia}a{color:#2f5d50}label{display:block;margin:16px 0}input,textarea,button{box-sizing:border-box;width:100%;font:inherit;padding:12px;border:1px solid #bdcbbf;border-radius:9px}button{background:#2f5d50;color:white;cursor:pointer}textarea{min-height:120px}#result{min-height:30px}</style></head><body><main>\'+content+\'</main></body></html>\').encode()\nCONTACT=_page(\'Contact\', \'<a href="/">Pillar Fabric home</a><h1>Contact Pillar Fabric</h1><p>Send an inquiry about any product. This form stores your message for review. It does not subscribe you to marketing or promise a response time. Do not include passwords, payment details or private source documents.</p><form id="contact"><label>Name<input name="name" required maxlength="160" autocomplete="name"></label><label>Email<input name="email" required type="email" maxlength="254" autocomplete="email"></label><label>Product<input name="product" maxlength="80" value="Pillar Fabric"></label><label>Message<textarea name="message" required maxlength="2000"></textarea></label><button>Send inquiry</button><p id="result" role="status" aria-live="polite"></p></form><p>Support: pillar@mail.instinct.com</p><script>const f=document.querySelector("form"),s=document.querySelector("#result"),b=f.querySelector("button");f.product.value=new URLSearchParams(location.search).get("product")||"Pillar Fabric";f.onsubmit=async e=>{e.preventDefault();b.disabled=true;b.textContent="Saving...";s.textContent="Saving your inquiry...";try{const r=await fetch("/api/launch-contact",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(new FormData(f)))});const j=await r.json();if(!r.ok)throw Error(j.error||"Could not save. Try again later.");s.textContent="Saved. Inquiry reference: "+j.reference+". No marketing subscription created.";f.reset()}catch(e){s.textContent=e.message}finally{b.disabled=false;b.textContent="Send inquiry"}}</script>\')\ndef _store_contact(data):\n    import secrets\n    ref=\'inq_\'+secrets.token_hex(8)\n    key=os.environ.get(\'DATABASE_URL\') or os.environ.get(\'STATE_DATABASE_URL\')\n    if not key:raise RuntimeError(\'Durable inquiry storage unavailable\')\n    import psycopg\n    with psycopg.connect(key,connect_timeout=10) as con,con.cursor() as cur:\n        cur.execute(\'CREATE TABLE IF NOT EXISTS launch_inquiries(reference TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL,product TEXT NOT NULL,message TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now())\')\n        cur.execute(\'INSERT INTO launch_inquiries(reference,name,email,product,message) VALUES(%s,%s,%s,%s,%s)\',(ref,data[\'name\'],data[\'email\'],data[\'product\'],data[\'message\']))\n    return ref\n\nclass SeoSlots:\n    def __init__(self, app):\n        self.app = app\n\n    async def __call__(self, scope, receive, send):\n        if scope["type"] != "http":\n            return await self.app(scope, receive, send)\n        if scope.get("method") in ("GET", "HEAD") and scope["path"] == f"/{INDEXNOW_KEY}.txt":\n            body = INDEXNOW_KEY.encode()\n            await send({"type": "http.response.start", "status": 200, "headers": [(b"content-type", b"text/plain; charset=utf-8"), (b"content-length", str(len(body)).encode())]})\n            return await send({"type": "http.response.body", "body": body})\n        host=dict(scope.get(\'headers\',[])).get(b\'host\',b\'\').decode().split(\':\')[0]\n        path=scope[\'path\']\n        async def respond(body,status=200,kind=b\'text/html; charset=utf-8\',headers=[]):\n            await send({\'type\':\'http.response.start\',\'status\':status,\'headers\':[(b\'content-type\',kind),(b\'content-length\',str(len(body)).encode())]+headers})\n            await send({\'type\':\'http.response.body\',\'body\':b\'\' if scope[\'method\']==\'HEAD\' else body})\n        if path==\'/launch-favicon.svg\':return await respond(FAVICON.encode(),kind=b\'image/svg+xml\')\n        if path==\'/contact\' and scope[\'method\'] in (\'GET\',\'HEAD\'):\n            if host!=\'pillar-fabric.onrender.com\':return await respond(b\'\',302,headers=[(b\'location\',(\'https://pillar-fabric.onrender.com/contact?product=\'+host).encode())])\n            return await respond(CONTACT)\n        if path==\'/api/launch-contact\' and scope[\'method\']==\'POST\':\n            if host!=\'pillar-fabric.onrender.com\':return await respond(b\'{"error":"Use the Pillar Fabric contact page."}\',400,b\'application/json\')\n            raw=b\'\'\n            while True:\n                event=await receive();raw+=event.get(\'body\',b\'\')\n                if len(raw)>5000:return await respond(b\'{"error":"Message is too large."}\',413,b\'application/json\')\n                if not event.get(\'more_body\'):break\n            try:\n                d=json.loads(raw);d={k:str(d.get(k,\'\')).strip() for k in (\'name\',\'email\',\'product\',\'message\')}\n                if not d[\'name\'] or len(d[\'name\'])>160 or not re.fullmatch(r\'[^@\\s]+@[^@\\s]+\\.[^@\\s]+\',d[\'email\']) or len(d[\'email\'])>254 or len(d[\'product\'])>80 or not d[\'message\'] or len(d[\'message\'])>2000:raise ValueError()\n            except Exception:return await respond(b\'{"error":"Check your name, email and message."}\',400,b\'application/json\')\n            try:\n                import asyncio\n                ref=await asyncio.to_thread(_store_contact,d)\n            except Exception:return await respond(b\'{"error":"We could not save your inquiry. Try later or email pillar@mail.instinct.com."}\',503,b\'application/json\')\n            return await respond(json.dumps({\'ok\':True,\'reference\':ref}).encode(),kind=b\'application/json\')\n        m = OG_PATH_RE.match(scope["path"])\n        if m and scope.get("method") in ("GET", "HEAD") and m.group(1) in _OG_IMAGES:\n            img = base64.b64decode(_OG_IMAGES[m.group(1)])\n            await send({"type": "http.response.start", "status": 200, "headers": [(b"content-type", b"image/png"), (b"cache-control", b"public, max-age=86400"), (b"content-length", str(len(img)).encode())]})\n            return await send({"type": "http.response.body", "body": b"" if scope["method"] == "HEAD" else img})\n        host = dict((k.lower(), v) for k, v in scope.get("headers", [])).get(b"host", b"").decode("latin-1")\n        path = scope["path"]\n        state = {"html": False, "start": None,"notfound":False}\n        chunks = []\n\n        async def wrapped(message):\n            if message["type"] == "http.response.start":\n                ct = dict((k.lower(), v) for k, v in message.get("headers", [])).get(b"content-type", b"")\n                state[\'notfound\']=message.get(\'status\')==404 and scope[\'method\'] in (\'GET\',\'HEAD\') and not path.startswith((\'/api/\',\'/mcp\',\'/static/\',\'/og/\')) and \'.\' not in path.rsplit(\'/\',1)[-1]\n                state["html"] = (b"text/html" in ct and message.get("status") == 200) or state[\'notfound\']\n                if state["html"]:\n                    state["start"] = message\n                    return\n                return await send(message)\n            if message["type"] == "http.response.body" and state["html"]:\n                chunks.append(message.get("body", b""))\n                if message.get("more_body"):\n                    return\n                body = b"".join(chunks)\n                if state[\'notfound\']:body=_page(\'Page not found\',\'<a href="/">Pillar Fabric product home</a><h1>Page not found</h1><p>This link may have moved or been typed incorrectly.</p><p><a href="/">Open the home page</a> or <a href="/contact">contact us</a>.</p>\')\n                text=body.decode(\'utf-8\',\'ignore\');esc=lambda x:_html.escape(x,quote=True)\n                title=_attr(text,r\'<title[^>]*>(.*?)</title>\') or \'Pillar Fabric product\'\n                if not re.search(r\'<meta[^>]+name=[\\"\\\']description\',text,re.I):body=body.replace(b\'</head>\',(\'<meta name="description" content="\'+esc(title+\'. Product information and tools from Pillar Fabric.\')+\'"></head>\').encode(),1)\n                if not re.search(r\'<link[^>]+rel=[\\"\\\'][^\\"\\\']*icon\',text,re.I):body=body.replace(b\'</head>\',b\'<link rel="icon" href="/launch-favicon.svg"></head>\',1)\n                if b\'<title\' not in body.lower():body=body.replace(b\'</head>\',b\'<title>Pillar Fabric product</title></head>\',1)\n                # Compress external photographic assets at their existing image source.\n                body=re.sub(rb\'(https://images\\.unsplash\\.com/[^\\"\\\'<> ]+)\',lambda m:m.group(1).replace(b\'fm=jpg\',b\'fm=webp\').replace(b\'fm=png\',b\'fm=webp\'),body)\n                if b\'launch-contact-link\' not in body and not path.startswith((\'/app\',\'/console\',\'/demo\',\'/s/\',\'/chat\',\'/workspace\',\'/ops\')):\n                    body=body.replace(b\'</body>\',b\'<footer id="launch-contact-link" style="padding:20px;text-align:center;font:14px system-ui"><a href="/contact">Contact Pillar Fabric</a></footer></body>\',1)\n\n                add = _verify_block()\n                if b\'"Organization"\' not in body:\n                    add += _org_block()\n                if b"</head>" in body:\n                    try:\n                        social, body = _social_block(body, host, path)\n                        add += social\n                    except Exception:\n                        pass\n                if add and b"</head>" in body:\n                    body = body.replace(b"</head>", add + b"</head>", 1)\n                headers = [(k, v) for k, v in state["start"]["headers"] if k.lower() != b"content-length" and not (state["notfound"] and k.lower()==b"content-type")]\n                if state["notfound"]:headers.append((b"content-type",b"text/html; charset=utf-8"))\n                headers.append((b"content-length", str(len(body)).encode()))\n                await send({**state["start"], "headers": headers})\n                return await send({"type": "http.response.body", "body": body})\n            return await send(message)\n\n        await self.app(scope, receive, wrapped)\n',_launch_ns)
app=_launch_ns["SeoSlots"](app)
if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=int(os.environ.get("PORT", "8000")))
